import type React from "react"
import { useId, useRef, useState } from "react"
import { ArrowDown, ArrowRight } from "lucide-react"
import { SocialLinks, socials } from "@/components/social-icons"
import { experience, humance } from "@/data/profile"

interface Token {
  text: string
  className?: string
}

const [currentJob] = experience
const productNames = humance.products.map((p) => p.name)

const plain = (text: string): Token => ({ text })
const keyword = (text: string): Token => ({ text, className: "text-sky-300" })
const str = (text: string): Token => ({
  text: `"${text}"`,
  className: "text-amber-200",
})
const list = (items: readonly string[]): Token[] => [
  plain("["),
  ...items.flatMap((item, i) =>
    i === 0 ? [str(item)] : [plain(", "), str(item)]
  ),
  plain("]"),
]
const prop = (name: Token, value: Token[], comma = true): Token[] => [
  plain("  "),
  name,
  plain(": "),
  ...value,
  ...(comma ? [plain(",")] : []),
]

const tsLines: Token[][] = [
  [
    keyword("const"),
    plain(" "),
    { text: "sabuj", className: "text-white" },
    plain(" = {"),
  ],
  prop({ text: "role", className: "text-slate-200" }, [str(currentJob.role)]),
  prop({ text: "company", className: "text-slate-200" }, [
    str(currentJob.company),
  ]),
  prop({ text: "building", className: "text-slate-200" }, list(productNames)),
  prop(
    { text: "stack", className: "text-slate-200" },
    list(["Next.js", "Node.js", "MongoDB", "AI agents"])
  ),
  prop({ text: "location", className: "text-slate-200" }, [str("Bangladesh")]),
  prop({ text: "remote", className: "text-slate-200" }, [
    { text: String(Boolean(currentJob.remote)), className: "text-emerald-300" },
  ]),
  [plain("}")],
]

const stackGroups: [string, string[]][] = [
  ["frontend", ["Next.js", "React", "TypeScript"]],
  ["backend", ["Node.js", "Express", "Socket.io"]],
  ["data", ["MongoDB", "Redis"]],
  ["ai", ["LLMs", "AI agents", "MCP"]],
]

const jsonLines: Token[][] = [
  [plain("{")],
  ...stackGroups.map(([group, items], i) =>
    prop(str(group), list(items), i < stackGroups.length - 1)
  ),
  [plain("}")],
]

const mdLines: Token[][] = [
  [{ text: "# Now", className: "text-sky-300" }],
  [plain(" ")],
  [
    { text: "- ", className: "text-emerald-300" },
    plain(`${currentJob.role} at ${currentJob.company} (${currentJob.period})`),
  ],
  [
    { text: "- ", className: "text-emerald-300" },
    plain(`Building ${productNames.join(" and ")}`),
  ],
  [
    { text: "- ", className: "text-emerald-300" },
    plain("Working remotely from Bangladesh"),
  ],
]

const files = [
  { name: "sabuj.ts", lines: tsLines },
  { name: "stack.json", lines: jsonLines },
  { name: "now.md", lines: mdLines },
]

const lineLength = (line: Token[]) =>
  line.reduce((total, token) => total + token.text.length, 0)

const ProfileCodeCard = () => {
  const [activeIndex, setActiveIndex] = useState(0)
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([])
  const baseId = useId()
  const lastIndex = files.length - 1
  const activeFile = files[activeIndex]

  const selectTab = (index: number) => {
    setActiveIndex(index)
    tabRefs.current[index]?.focus()
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const target: Record<string, number> = {
      ArrowRight: activeIndex === lastIndex ? 0 : activeIndex + 1,
      ArrowLeft: activeIndex === 0 ? lastIndex : activeIndex - 1,
      Home: 0,
      End: lastIndex,
    }
    if (
      !(event.key in target) ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey
    )
      return
    event.preventDefault()
    selectTab(target[event.key])
  }

  return (
    <div className="reveal relative mx-auto w-full min-w-0 max-w-xl rounded-2xl border border-slate-800 bg-slate-900 shadow-2xl shadow-black/40 print:hidden lg:mx-0 lg:max-w-none">
      <div className="flex items-center gap-2 border-b border-white/10 px-4 py-1.5">
        <span
          aria-hidden="true"
          className="hidden size-3 rounded-full bg-rose-400/80 sm:block"
        />
        <span
          aria-hidden="true"
          className="hidden size-3 rounded-full bg-amber-300/80 sm:block"
        />
        <span
          aria-hidden="true"
          className="hidden size-3 rounded-full bg-emerald-400/80 sm:block"
        />
        <div
          role="tablist"
          aria-label="Profile files"
          onKeyDown={onKeyDown}
          className="flex min-w-0 gap-1 overflow-x-auto p-0.5 sm:ml-3"
        >
          {files.map((file, index) => {
            const selected = index === activeIndex
            return (
              <button
                key={file.name}
                ref={(el) => {
                  tabRefs.current[index] = el
                }}
                type="button"
                role="tab"
                id={`${baseId}-tab-${index}`}
                aria-selected={selected}
                aria-controls={`${baseId}-panel`}
                tabIndex={selected ? 0 : -1}
                onClick={() => setActiveIndex(index)}
                className={`cursor-pointer rounded-md px-2.5 py-2.5 font-mono text-xs transition-colors focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-primary ${
                  selected
                    ? "bg-white/10 text-slate-100 underline decoration-primary decoration-2 underline-offset-6"
                    : "text-slate-400 hover:text-slate-200"
                }`}
              >
                {file.name}
              </button>
            )
          })}
        </div>
      </div>
      <pre
        id={`${baseId}-panel`}
        role="tabpanel"
        aria-labelledby={`${baseId}-tab-${activeIndex}`}
        tabIndex={0}
        className="overflow-x-auto p-4 font-mono text-xs leading-6 text-slate-300 focus-visible:outline-2 focus-visible:outline-primary sm:p-5 xl:text-[13px]"
      >
        <code key={activeFile.name}>
          {activeFile.lines.map((line, i) => {
            const isLast = i === activeFile.lines.length - 1
            return (
              <span
                key={i}
                className={`type-line block whitespace-pre ${isLast ? "type-caret" : ""}`}
                style={
                  {
                    "--chars": lineLength(line) + (isLast ? 1 : 0),
                    "--line": i,
                  } as React.CSSProperties
                }
              >
                {line.map((token, j) => (
                  <span key={j} className={token.className}>
                    {token.text}
                  </span>
                ))}
              </span>
            )
          })}
        </code>
      </pre>
    </div>
  )
}

